/*
 * bemani_dll_host.c -- minimal Win32 host process for DLL-based Konami Bemani PC games.
 *
 * Konami Bemani PC games ship a modules/launch.dll as the only executable unit
 * (no game.exe).  Windows cannot CreateProcessA a DLL directly.  This host
 * bridges the gap: the konami_bemani module spawns THIS exe suspended, injects
 * the hook, then resumes.  The hook lands before LoadLibrary(launch.dll), which
 * means every API intercept is in place before the game's own init runs.
 *
 * Usage (generated by konami_bemani_main.c -- never called by the user):
 *   bemani_dll_host.exe <absolute-path-to-launch.dll>
 *
 * The CWD is set to the game root by the spawning module, NOT to the modules\
 * subfolder.  AVS and other Konami libraries search for prop\ config relative
 * to CWD, so getting this right matters.
 *
 * Build: 32-bit console subsystem EXE -- see build_module.sh.
 */

#include <windows.h>
#include <stdio.h>

int main(int argc, char **argv)
{
    /*
     * APC-flush: if the spawning module queued a LoadLibraryA APC on this
     * thread (primary inject path), process it NOW, before the game DLL loads.
     * SleepEx(0, TRUE) is an alertable wait that returns immediately once the
     * queue is drained.  Without this, the main thread never enters an
     * alertable state and the APC fires too late (or not at all).
     */
    SleepEx(0, TRUE);

    if (argc < 2 || !argv[1] || !argv[1][0]) {
        fprintf(stderr, "[bemani_host] usage: bemani_dll_host.exe <launch.dll>\n");
        fflush(stderr);
        return 1;
    }

    fprintf(stderr, "[bemani_host] loading %s\n", argv[1]);
    fflush(stderr);

    HMODULE mod = LoadLibraryA(argv[1]);
    if (!mod) {
        fprintf(stderr, "[bemani_host] LoadLibrary(%s) failed: %lu\n",
                argv[1], GetLastError());
        fflush(stderr);
        return 1;
    }

    typedef int (*entry_fn)(int, char **);
    entry_fn entry = (entry_fn)(uintptr_t)GetProcAddress(mod, "dll_entry_main");
    if (!entry) {
        fprintf(stderr, "[bemani_host] dll_entry_main not found in %s\n", argv[1]);
        fflush(stderr);
        FreeLibrary(mod);
        return 1;
    }

    fprintf(stderr, "[bemani_host] calling dll_entry_main\n");
    fflush(stderr);

    /* Pass our own argc/argv so launch.dll receives the same command line it
     * would have gotten from a native launcher.  Most games ignore these. */
    return entry(argc, argv);
}
